def transform(grid):
    g = np.array(grid)
    bg = background(g)
    ys, xs = np.where(g == 5)
    h = ys.max() - ys.min() + 1
    w = xs.max() - xs.min() + 1
    out = np.full((h, w), bg, dtype=int)
    emit(out, f"Allocate a {h}x{w} canvas, the size of the colour-5 block.")
    lines = []
    for c in np.unique(g):
        if c == bg or c == 5:
            continue
        cy, cx = np.where(g == c)
        hgt = cy.max() - cy.min() + 1
        wid = cx.max() - cx.min() + 1
        if wid > hgt:
            lines.append(('h', int(cy.min()), int(c)))
        else:
            lines.append(('v', int(cx.min()), int(c)))
    horiz = sum(1 for l in lines if l[0] == 'h') >= sum(1 for l in lines if l[0] == 'v')
    lines.sort(key=lambda l: l[1])
    for i, (o, pos, c) in enumerate(lines):
        if horiz:
            if i < h:
                out[i, :] = c
                emit(out, f"Row {i} gets colour {c}, the {i+1}th horizontal line from the top.")
        else:
            if i < w:
                out[:, i] = c
                emit(out, f"Column {i} gets colour {c}, the {i+1}th vertical line from the left.")
    emit(out, "Final grid: the lines' colours stacked in order inside the block's size.")
    return out
